using Amiga;
using Amiga.MUI;
using CopperOS.MuiMaster;
using CopperSharp.Sdk.Amiga;
using static CopperOS.MuiMaster.MuiListCore;

namespace CopperOS.MuiMaster.NativeRoot;

// Named fixed-width storage used by the dispatcher qualification root.  The
// platform itself is a four-byte state token; keeping this adjacent record
// live prevents the freestanding compiler from overlapping that ref receiver
// with the packet locals while the interface-based lifecycle is in flight.
public struct MuiNativeDispatcherFrame
{
	public uint Guard0;
	public uint Guard1;
	public uint Guard2;
	public uint Guard3;
	public uint Guard4;
	public uint Guard5;

	public static void Initialize(ref MuiNativeDispatcherFrame frame)
	{
		frame.Guard0 = 0xD15A0000;
		frame.Guard1 = 0xD15A0001;
		frame.Guard2 = 0xD15A0002;
		frame.Guard3 = 0xD15A0003;
		frame.Guard4 = 0xD15A0004;
		frame.Guard5 = 0xD15A0005;
	}

	public static bool IsValid(ref MuiNativeDispatcherFrame frame) =>
		frame.Guard0 == 0xD15A0000 && frame.Guard1 == 0xD15A0001 &&
		frame.Guard2 == 0xD15A0002 && frame.Guard3 == 0xD15A0003 &&
		frame.Guard4 == 0xD15A0004 && frame.Guard5 == 0xD15A0005;
}

[System.Runtime.InteropServices.StructLayout(
	System.Runtime.InteropServices.LayoutKind.Sequential, Pack = 2)]
public struct MuiNativeHookRecord
{
	public const uint Size = 20;
	public APTR Successor;
	public APTR Predecessor;
	public APTR Entry;
	public APTR SubEntry;
	public APTR Data;
}

public static class MuiNativeHookRecordCodec
{
	public static bool Write(ref MuiNativeHeadlessPlatform platform,
		APTR address, MuiNativeHookRecord value)
	{
		if (address.IsNull || !platform.IsMapped(address, MuiNativeHookRecord.Size))
			return false;
		APTR.WriteUInt32(address, 0, value.Successor.Raw);
		APTR.WriteUInt32(address, 4, value.Predecessor.Raw);
		APTR.WriteUInt32(address, 8, value.Entry.Raw);
		APTR.WriteUInt32(address, 12, value.SubEntry.Raw);
		APTR.WriteUInt32(address, 16, value.Data.Raw);
		return true;
	}
}

[System.Runtime.InteropServices.StructLayout(
	System.Runtime.InteropServices.LayoutKind.Sequential, Pack = 2)]
public struct MuiNativeHookCallRecord
{
	public const uint Size = 12;
	public APTR Hook;
	public APTR Object;
	public APTR Message;
}

public static class MuiNativeHookCallRecordCodec
{
	public static bool TryRead(ref MuiNativeHeadlessPlatform platform,
		APTR address, out MuiNativeHookCallRecord value)
	{
		value = default;
		if (address.IsNull || !platform.IsMapped(address,
			MuiNativeHookCallRecord.Size)) return false;
		value.Hook = APTR.FromPointer(APTR.ReadUInt32(address, 0));
		value.Object = APTR.FromPointer(APTR.ReadUInt32(address, 4));
		value.Message = APTR.FromPointer(APTR.ReadUInt32(address, 8));
		return true;
	}
}

public static class MuiNativeRoots
{
	// MG2091: qualify the local Layers fallback through its named packed Exec
	// List record without pulling the large application graph into this root.
	public static uint LayersExecListStructRoot()
	{
		var platform = new MuiNativeHeadlessPlatform();
		platform.Reset();
		var address = APTR.FromPointer(0x0004F200);
		var expected = new Amiga.List
		{
			Head = APTR.FromPointer(0x0004F300),
			Tail = APTR.FromPointer(0x0004F304),
			TailPred = APTR.FromPointer(0x0004F308),
			Type = NodeType.Library,
			Padding = 0x5A,
		};
		if (!LayersExecListCodec.Write(ref platform, address, expected))
			return 1;
		if (!LayersExecListCodec.TryRead(ref platform, address,
			out var actual)) return 2;
		if (actual.Head != expected.Head) return 3;
		if (actual.Tail != expected.Tail) return 4;
		if (actual.TailPred != expected.TailPred) return 5;
		if (actual.Type != expected.Type) return 6;
		return 42;
	}

	public static uint HeadlessCoreRoot()
	{
		var platform = new MuiNativeHeadlessPlatform();
		platform.Reset();
		const uint privateRoot = 0x00035F00;
		const uint state = 0x00036000;
		const uint name = 0x00036100;
		APTR.WriteUInt8(APTR.FromPointer(name), 0, (byte)'N');
		APTR.WriteUInt8(APTR.FromPointer(name), 1, (byte)'o');
		APTR.WriteUInt8(APTR.FromPointer(name), 2, (byte)'t');
		APTR.WriteUInt8(APTR.FromPointer(name), 3, (byte)'i');
		APTR.WriteUInt8(APTR.FromPointer(name), 4, (byte)'f');
		APTR.WriteUInt8(APTR.FromPointer(name), 5, (byte)'y');
		APTR.WriteUInt8(APTR.FromPointer(name), 6, 0);
		if (!MuiMasterLifecycleCore.Create(ref platform,
			APTR.FromPointer(privateRoot), APTR.FromPointer(state))) return 1;
		var cl = MuiHeadlessObjectCore.RegisterBuiltinClass(ref platform,
			APTR.FromPointer(state), APTR.FromPointer(name), APTR.Null, 8,
			APTR.FromPointer(1)).Raw;
		if (cl == 0) return 2;
		var family = MuiHeadlessObjectCore.CreateObjectA(ref platform,
			APTR.FromPointer(state), APTR.FromPointer(cl), APTR.Null).Raw;
		var child = MuiHeadlessObjectCore.CreateObjectA(ref platform,
			APTR.FromPointer(state), APTR.FromPointer(cl), APTR.Null).Raw;
		if (family == 0 || child == 0) return 3;
		if (!MuiFamilyCore.AddTail(ref platform, APTR.FromPointer(state),
			APTR.FromPointer(family), APTR.FromPointer(child))) return 4;
		const uint data = 0x00036200;
		APTR.WriteUInt32(APTR.FromPointer(data), 0, 0x11223344);
		if (!MuiStoreCore.DataspaceAdd(ref platform, APTR.FromPointer(state),
			APTR.FromPointer(family), 7, APTR.FromPointer(data), 4)) return 5;
		const uint follow = 0x00036220;
		APTR.WriteUInt32(APTR.FromPointer(follow), 0, 0x90000001);
		APTR.WriteUInt32(APTR.FromPointer(follow), 4, 1233727793);
		if (!MuiNotifyCore.Add(ref platform, APTR.FromPointer(state),
			APTR.FromPointer(family), 0x80420001, 1233727793,
			APTR.FromPointer(child), 2, APTR.FromPointer(follow))) return 6;
		const uint packet = 0x00036240;
		APTR.WriteUInt32(APTR.FromPointer(packet), 0, 0x8042549A);
		APTR.WriteUInt32(APTR.FromPointer(packet), 4, 0x80420001);
		APTR.WriteUInt32(APTR.FromPointer(packet), 8, 42);
		if (MuiHeadlessDispatcher.Dispatch(ref platform, APTR.FromPointer(state),
			APTR.FromPointer(family), APTR.FromPointer(packet)) == 0) return 7;
		if (!MuiSemaphoreCore.Attempt(ref platform, APTR.FromPointer(state),
			APTR.FromPointer(family)) || !MuiSemaphoreCore.Release(ref platform,
			APTR.FromPointer(state), APTR.FromPointer(family))) return 8;
		if (!MuiMasterLifecycleCore.Dispose(ref platform,
			APTR.FromPointer(privateRoot))) return 9;
		return 42;
	}

	// MG603 headless creation TagItem closure. Creation tags are authored and
	// consumed as named MuiAslTagItemRecord values; traversal arithmetic remains
	// inside the shared TagItem vector codec. The full object factory route is
	// host-covered; this native root isolates the guest-resident tag walk.
	public static uint HeadlessCreationTagCodecRoot()
	{
		var platform = new MuiNativeHeadlessPlatform();
		platform.Reset();
		const uint tags = 0x00050F20;
		const uint attribute = 0x80420001;
		var baseAddress = APTR.FromPointer(tags);
		if (!MuiAslTagItemCodec.Write(ref platform, baseAddress,
			new MuiAslTagItemRecord { Tag = attribute, Data = 77 }) ||
			!MuiAslTagItemCodec.Write(ref platform,
				APTR.FromPointer(tags + MuiAslTagItemRecord.Size),
				new MuiAslTagItemRecord { Tag = MuiAslTagListCore.TagDone })) return 1;
		var cursor = default(MuiAslTagItemCursor);
		cursor.Base = baseAddress;
		if (!MuiAslTagItemVectorCodec.TryGetEntry(ref platform, cursor,
			out var first) || !MuiAslTagItemCodec.TryRead(ref platform, first,
			out var firstItem) || firstItem.Tag != attribute || firstItem.Data != 77)
			return 2;
		if (!MuiAslTagItemVectorCodec.TryAdvance(ref cursor, 1) ||
			!MuiAslTagItemVectorCodec.TryGetEntry(ref platform, cursor,
				out var terminator) || !MuiAslTagItemCodec.TryRead(ref platform,
				terminator, out var terminatorItem) ||
			terminatorItem.Tag != MuiAslTagListCore.TagDone) return 3;
		if (cursor.Index != 1) return 4;
		return 42;
	}

	// Focused MG2141 Headless method-header closure. The named one-ULONG record
	// is qualified through the shared guest-storage adapter; dispatcher and
	// specialized payload records remain in HeadlessCoreRoot.
	public static uint HeadlessMethodHeaderCodecRoot()
	{
		var platform = new MuiNativeHeadlessPlatform();
		platform.Reset();
		const uint packet = 0x00050F20;
		var address = APTR.FromPointer(packet);
		const uint methodId = 0xC2468ACE;
		if (!MuiHeadlessMethodHeaderCodec.WriteValue(ref platform, address,
			methodId)) return 1;
		if (!MuiHeadlessMethodHeaderCodec.TryReadValue(ref platform, address,
			out var readMethod) || readMethod != methodId) return 2;
		if (!MuiHeadlessMethodMessageRecordMemoryCodec.TryGetAddress(ref platform,
			address, MuiHeadlessMethodMessageField.MethodId, out var methodAddress) ||
			methodAddress.Raw != packet) return 3;
		if (MuiHeadlessMethodHeaderCodec.TryReadValue(ref platform,
			APTR.FromPointer(0x00050FFF), out _)) return 4;
		if (MuiHeadlessMethodHeaderCodec.WriteValue(ref platform, APTR.Null,
			methodId)) return 5;
		return 42;
	}

	// MG1380 native proof for the named BOOPSI OM_SET/OM_UPDATE records. Both
	// packets are written and read through their struct codecs; truncated
	// records fail before any field can be consumed.
	public static uint HeadlessOmRecordCodecRoot()
	{
		var platform = new MuiNativeHeadlessPlatform();
		platform.Reset();
		var setAddress = APTR.FromPointer(0x00050F20);
		var set = default(MuiHeadlessOmSetMessage);
		set.Attributes = APTR.FromPointer(0x00050D00);
		set.GadgetInfo = APTR.FromPointer(0x00050D20);
		if (!MuiHeadlessOmSetMessageCodec.TryWrite(ref platform, setAddress, set) ||
			!MuiHeadlessOmSetMessageCodec.TryRead(ref platform, setAddress,
				out var readSet) || readSet.MethodId !=
			MuiHeadlessOmSetMessageCodec.Method || readSet.Attributes.Raw !=
			set.Attributes.Raw || readSet.GadgetInfo.Raw != set.GadgetInfo.Raw)
			return 1;
		if (!MuiHeadlessOmSetMessageMemoryCodec.TryGetAddress(ref platform,
			setAddress, MuiHeadlessOmSetField.GadgetInfo, out var gadgetInfoAddress) ||
			gadgetInfoAddress.Raw != setAddress.Raw + MuiHeadlessOmSetMessage.GadgetInfoOffset)
			return 2;

		var updateAddress = APTR.FromPointer(0x00050F40);
		var update = default(MuiHeadlessOmUpdateMessage);
		update.Attributes = APTR.FromPointer(0x00050D40);
		update.GadgetInfo = APTR.FromPointer(0x00050D60);
		update.Flags = 0xA5A5u;
		if (!MuiHeadlessOmUpdateMessageCodec.TryWrite(ref platform,
			updateAddress, update) ||
			!MuiHeadlessOmUpdateMessageCodec.TryRead(ref platform, updateAddress,
				out var readUpdate) || readUpdate.MethodId !=
			MuiHeadlessOmUpdateMessageCodec.Method || readUpdate.Attributes.Raw !=
			update.Attributes.Raw || readUpdate.GadgetInfo.Raw !=
			update.GadgetInfo.Raw || readUpdate.Flags != update.Flags)
			return 3;
		if (!MuiHeadlessOmUpdateMessageMemoryCodec.TryGetAddress(ref platform,
			updateAddress, MuiHeadlessOmUpdateField.Flags, out var flagsAddress) ||
			flagsAddress.Raw != updateAddress.Raw + MuiHeadlessOmUpdateMessage.FlagsOffset ||
			!MuiHeadlessOmUpdateMessageMemoryCodec.TryReadUInt32(ref platform,
				updateAddress, MuiHeadlessOmUpdateField.Flags, out var flags) ||
			flags != update.Flags) return 3;

		if (MuiHeadlessOmSetMessageCodec.TryRead(ref platform,
			APTR.FromPointer(0x00050FFC), out _) ||
			MuiHeadlessOmUpdateMessageCodec.TryRead(ref platform,
				APTR.FromPointer(0x00050FF8), out _) ||
			MuiHeadlessOmUpdateMessageCodec.TryWrite(ref platform,
				APTR.FromPointer(0x00050FF8), update)) return 4;
		return 42;
	}

	// Focused qualification for the sequential named-record headless message
	// codecs. The method header, OM_SET, and OM_UPDATE shapes are all exercised
	// through the production declaration-order bridge, including bounds checks.
	public static uint HeadlessMessageStructPacketCodecRoot()
	{
		var platform = new MuiNativeHeadlessPlatform();
		platform.Reset();
		var packet = APTR.FromPointer(0x00050F20);
		if (!MuiHeadlessMessageStructCodec.TryWriteMethod(ref platform, packet,
			0x80420001u) ||
			!MuiHeadlessMessageStructCodec.TryReadMethodIdValue(ref platform, packet,
				out var method) || method != 0x80420001u) return 1;
		var set = default(MuiHeadlessOmSetMessage);
		set.Attributes = APTR.FromPointer(0x00050D00);
		set.GadgetInfo = APTR.FromPointer(0x00050D20);
		if (!MuiHeadlessMessageStructCodec.TryWriteOmSet(ref platform, packet, set) ||
			!MuiHeadlessMessageStructCodec.TryReadOmSet(ref platform, packet,
				out var setRead) || setRead.Attributes.Raw != 0x00050D00 ||
			setRead.GadgetInfo.Raw != 0x00050D20) return 2;
		var update = default(MuiHeadlessOmUpdateMessage);
		update.Attributes = APTR.FromPointer(0x00050D40);
		update.GadgetInfo = APTR.FromPointer(0x00050D60);
		update.Flags = 0xA5A5u;
		if (!MuiHeadlessMessageStructCodec.TryWriteOmUpdate(ref platform, packet,
			update) || !MuiHeadlessMessageStructCodec.TryReadOmUpdate(ref platform,
			packet, out var updateRead) || updateRead.Attributes.Raw != 0x00050D40 ||
			updateRead.GadgetInfo.Raw != 0x00050D60 ||
			updateRead.Flags != 0xA5A5u) return 3;
		if (MuiHeadlessMessageStructCodec.TryReadOmSet(ref platform,
			APTR.FromPointer(0x00050FFC), out _) ||
			MuiHeadlessMessageStructCodec.TryReadOmUpdate(ref platform,
				APTR.FromPointer(0x00050FF8), out _) ||
			MuiHeadlessMessageStructCodec.TryReadMethodIdValue(ref platform,
				APTR.Null, out _)) return 4;
		return 42;
	}

	// Focused MorphOS MUIM_Family_GetChild closure. The fixed packet is
	// decoded into a named struct and all selector forms use the guest Family
	// topology without managed iteration.
	public static uint FamilyGetChildRoot()
	{
		var platform = new MuiNativeHeadlessPlatform();
		platform.Reset();
		const uint firstNode = 0x00036820;
		const uint secondNode = 0x00036830;
		const uint thirdNode = 0x00036840;
		const uint firstObject = 0x00036900;
		const uint secondObject = 0x00036910;
		const uint thirdObject = 0x00036920;
		const uint packet = 0x00036940;
		if (!MuiFamilyGetChildCore.WriteChildRecord(ref platform,
			APTR.FromPointer(firstNode), APTR.FromPointer(secondNode), APTR.Null,
			APTR.FromPointer(firstObject))) return 1;
		if (!MuiFamilyGetChildCore.WriteChildRecord(ref platform,
			APTR.FromPointer(secondNode), APTR.FromPointer(thirdNode),
			APTR.FromPointer(firstNode), APTR.FromPointer(secondObject))) return 2;
		if (!MuiFamilyGetChildCore.WriteChildRecord(ref platform,
			APTR.FromPointer(thirdNode), APTR.Null, APTR.FromPointer(secondNode),
			APTR.FromPointer(thirdObject))) return 3;
		if (!MuiFamilyGetChildCore.WriteRecord(ref platform,
			APTR.FromPointer(packet), MuiFamilyGetChildCore.First, APTR.Null)) return 41;
		var firstResult = MuiFamilyGetChildCore.DispatchRecord(ref platform,
			APTR.FromPointer(firstNode), APTR.FromPointer(thirdNode),
			APTR.FromPointer(packet));
		if (firstResult != firstObject) return 4;
		if (!MuiFamilyGetChildCore.WriteRecord(ref platform,
			APTR.FromPointer(packet), MuiFamilyGetChildCore.Last, APTR.Null) ||
			MuiFamilyGetChildCore.DispatchRecord(ref platform,
			APTR.FromPointer(firstNode), APTR.FromPointer(thirdNode),
			APTR.FromPointer(packet)) != thirdObject) return 5;
		if (!MuiFamilyGetChildCore.WriteRecord(ref platform,
			APTR.FromPointer(packet), MuiFamilyGetChildCore.Next,
			APTR.FromPointer(firstObject)) ||
			MuiFamilyGetChildCore.DispatchRecord(ref platform,
			APTR.FromPointer(firstNode), APTR.FromPointer(thirdNode),
			APTR.FromPointer(packet)) != secondObject) return 6;
		if (!MuiFamilyGetChildCore.WriteRecord(ref platform,
			APTR.FromPointer(packet), MuiFamilyGetChildCore.Iterate,
			APTR.FromPointer(secondObject)) ||
			MuiFamilyGetChildCore.DispatchRecord(ref platform,
			APTR.FromPointer(firstNode), APTR.FromPointer(thirdNode),
			APTR.FromPointer(packet)) != thirdObject) return 7;
		if (!MuiFamilyGetChildCore.WriteRecord(ref platform,
			APTR.FromPointer(packet), MuiFamilyGetChildCore.Previous,
			APTR.FromPointer(thirdObject)) ||
			MuiFamilyGetChildCore.DispatchRecord(ref platform,
			APTR.FromPointer(firstNode), APTR.FromPointer(thirdNode),
			APTR.FromPointer(packet)) != secondObject) return 8;
		if (!MuiFamilyGetChildCore.WriteRecord(ref platform,
			APTR.FromPointer(packet), MuiFamilyGetChildCore.Previous, APTR.Null) ||
			MuiFamilyGetChildCore.DispatchRecord(ref platform,
			APTR.FromPointer(firstNode), APTR.FromPointer(thirdNode),
			APTR.FromPointer(packet)) != thirdObject) return 9;
		return 42;
	}

	// Focused ABI proof for the named MUIM_Family_GetChild packet codec. The
	// selector and reference fields round-trip as a struct, while a truncated
	// guest record is rejected before any Family topology is consulted.
	public static uint FamilyGetChildMessageCodecRoot()
	{
		var platform = new MuiNativeHeadlessPlatform();
		platform.Reset();
		const uint packetAddress = 0x00036580;
		const uint reference = 0x000365A0;
		var packet = default(MuiFamilyGetChildMessage);
		packet.MethodId = MuiFamilyGetChildMessageCodec.Method;
		packet.Number = MuiFamilyGetChildCore.Next;
		packet.Reference = APTR.FromPointer(reference);
		var storage = APTR.FromPointer(packetAddress);
		if (!MuiFamilyGetChildMessageCodec.Write(ref platform, storage, packet))
			return 1;
		if (!MuiFamilyGetChildMessageCodec.TryRead(ref platform, storage,
			out var decoded) || decoded.MethodId != packet.MethodId ||
			decoded.Number != packet.Number || decoded.Reference.Raw != reference)
			return 2;
		if (MuiFamilyGetChildMessageCodec.TryRead(ref platform,
			APTR.FromPointer(0x00050FFF), out _)) return 3;
		return 42;
	}

	// MG2126 native ABI proof for the method-only Family_GetChild header. The
	// one-ULONG named record is lowered through the shared storage codec, with
	// full-width values and truncated guest mappings rejected deterministically.
	public static uint FamilyGetChildMethodHeaderStructCodecRoot()
	{
		var platform = new MuiNativeHeadlessPlatform();
		platform.Reset();
		const uint packetAddress = 0x00036580;
		const uint methodId = 0xF1234567u;
		var storage = APTR.FromPointer(packetAddress);
		if (!MuiFamilyGetChildMethodHeaderCodec.WriteValue(ref platform, storage,
			methodId)) return 1;
		if (!MuiFamilyGetChildMethodHeaderCodec.TryReadValue(ref platform, storage,
			out var readMethodId) || readMethodId != methodId) return 2;
		if (MuiFamilyGetChildMethodHeaderCodec.TryReadValue(ref platform,
			APTR.FromPointer(0x00050FFF), out _)) return 3;
		if (MuiFamilyGetChildMethodHeaderCodec.WriteValue(ref platform,
			APTR.Null, methodId)) return 4;
		return 42;
	}

	// MG2330 native struct-first Family_GetChild field adapter closure. The
	// signed child selector and reference pointer are updated through the
	// complete named packet record; the method-only header remains a bounded
	// one-ULONG struct and sibling fields survive both paths.
	public static uint FamilyGetChildFieldStructRecordCodecRoot()
	{
		var platform = new MuiNativeHeadlessPlatform();
		platform.Reset();
		var address = APTR.FromPointer(0x00036580);
		var packet = new MuiFamilyGetChildMessage
		{
			MethodId = MuiFamilyGetChildMessageCodec.Method,
			Number = -4,
			Reference = APTR.FromPointer(0x000365A0),
		};
		if (!MuiFamilyGetChildMessageStructCodec.WriteRecord(ref platform,
			address, packet) ||
			!MuiFamilyGetChildMessageMemoryCodec.TryWriteUInt32(ref platform,
				address, MuiFamilyGetChildPacketField.Number, unchecked((uint)-7)) ||
			!MuiFamilyGetChildMessageMemoryCodec.TryWriteUInt32(ref platform,
				address, MuiFamilyGetChildPacketField.Reference, 0x000365C0) ||
			!MuiFamilyGetChildMessageMemoryCodec.TryWriteUInt32(ref platform,
				address, MuiFamilyGetChildPacketField.MethodId, 0xF1234567u)) return 1;
		if (!MuiFamilyGetChildMessageStructCodec.TryRead(ref platform, address,
			out var decoded) || decoded.MethodId != 0xF1234567u ||
			decoded.Number != -7 || decoded.Reference.Raw != 0x000365C0) return 2;
		if (!MuiFamilyGetChildMessageMemoryCodec.TryReadUInt32(ref platform,
			address, MuiFamilyGetChildPacketField.Number,
			out var number) || number != unchecked((uint)-7)) return 3;
		if (MuiFamilyGetChildMessageMemoryCodec.TryReadUInt32(ref platform,
			APTR.FromPointer(0x00050FFF), MuiFamilyGetChildPacketField.Number,
			out _) || MuiFamilyGetChildMessageMemoryCodec.TryWriteUInt32(
			ref platform, APTR.Null, MuiFamilyGetChildPacketField.Reference, 1)) return 4;
		return 42;
	}

	// MG2576 native proof for the Family_GetChild field cursor adapter. Typed
	// addresses are obtained by walking the named packet declaration order;
	// malformed records and unknown fields fail closed before scalar access.
	public static uint FamilyGetChildFieldCursorStructRecordCodecRoot()
	{
		var platform = new MuiNativeHeadlessPlatform();
		platform.Reset();
		var address = APTR.FromPointer(0x00036580);
		var packet = new MuiFamilyGetChildMessage
		{
			MethodId = MuiFamilyGetChildMessageCodec.Method,
			Number = -2,
			Reference = APTR.FromPointer(0x000365A0),
		};
		if (!MuiFamilyGetChildMessageStructCodec.WriteRecord(ref platform,
			address, packet)) return 1;
		if (!MuiFamilyGetChildMessageMemoryCodec.TryGetAddress(ref platform,
			address, MuiFamilyGetChildPacketField.MethodId, out var methodAddress) ||
			methodAddress.Raw != address.Raw ||
			!MuiFamilyGetChildMessageMemoryCodec.TryGetAddress(ref platform,
			address, MuiFamilyGetChildPacketField.Number, out var numberAddress) ||
			numberAddress.Raw != address.Raw + MuiFamilyGetChildMessage.FieldSize ||
			!MuiFamilyGetChildMessageMemoryCodec.TryGetAddress(ref platform,
			address, MuiFamilyGetChildPacketField.Reference, out var referenceAddress) ||
			referenceAddress.Raw != address.Raw + (MuiFamilyGetChildMessage.FieldSize * 2)) return 2;
		var fieldCursor = new MuiFamilyGetChildPacketFieldCursor
		{
			Message = address,
			Field = MuiFamilyGetChildPacketField.Reference,
		};
		if (!MuiFamilyGetChildPacketFieldCursorCodec.TryGetAddress(ref platform,
			fieldCursor, out var cursorAddress) || cursorAddress.Raw != address.Raw +
			(MuiFamilyGetChildMessage.FieldSize * 2))
			return 3;
		if (!MuiFamilyGetChildMessageMemoryCodec.TryWriteUInt32(ref platform,
			address, MuiFamilyGetChildPacketField.Number, unchecked((uint)-7)) ||
			!MuiFamilyGetChildMessageStructCodec.TryRead(ref platform, address,
			out var decoded) || decoded.MethodId != packet.MethodId ||
			decoded.Number != -7 || decoded.Reference.Raw != packet.Reference.Raw) return 4;
		if (MuiFamilyGetChildMessageMemoryCodec.TryGetAddress(ref platform,
			APTR.FromPointer(0x00050FFF), MuiFamilyGetChildPacketField.Number,
			out _) || MuiFamilyGetChildMessageMemoryCodec.TryGetAddress(ref platform,
			address, (MuiFamilyGetChildPacketField)255, out _)) return 5;
		return 42;
	}

	// MG2331 native struct-first Family mutation field adapter closure. Child,
	// Insert, Transfer, Reorder, method, and sort packets exchange named records;
	// the inline Reorder vector remains untouched by header updates.
	public static uint FamilyMutationFieldStructRecordCodecRoot()
	{
		var platform = new MuiNativeHeadlessPlatform();
		platform.Reset();
		var address = APTR.FromPointer(0x00036580);
		if (!MuiFamilyMutationMessageStructCodec.WriteRecord(ref platform, address,
