	// Compile the explicit-base MorphOS keymap call boundary without relying on
	// resident KeymapLibraryBase state or guest-message offsets.
	public static uint NativeKeymapCallBoundaryRoot()
	{
		var library = Exec.OpenLibraryRaw(CString.FromLiteral("keymap.library"), 0);
		if (library.IsNull) return 42;
		var translated = MuiNativeKeymapCalls.TryMapRawKey(library,
			APTR.FromPointer(1), out _);
		Exec.CloseLibrary(library);
		return translated ? 1u : 42u;
	}

