		APTR.WriteUInt8(address, 5, (byte)'m');
		APTR.WriteUInt8(address, 6, (byte)'u');
		APTR.WriteUInt8(address, 7, (byte)'i');
		APTR.WriteUInt8(address, 8, 0);
	}

