				APTR.FromPointer(second), -3)) return 4;

		APTR.WriteUInt32(APTR.FromPointer(packet), 0, 0x804280ECu);
		APTR.WriteUInt32(APTR.FromPointer(packet), 4, 0);
		APTR.WriteUInt32(APTR.FromPointer(packet), 8, storage);
