		if (!MuiListtreeCore.Open(ref platform, APTR.FromPointer(state), t,
			APTR.FromPointer(Root), root, 0)) return 12;
		if (MuiListtreeCore.VisibleCount(ref platform, APTR.FromPointer(state), t)
			!= 3) return 13;
