		var registry = default(MuiMccprefsRegistryRecord);
		registry.Gadget = APTR.FromPointer(0x00050C00);
		registry.Id = 7;
		registry.Params = 8;
		registry.Title = APTR.FromPointer(0x00050C40);
		registry.Attr = 0x80420000;
